import os, json, numpy as np

N = 26
SAFETY = 1e-9
P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
OUT = 'storage/noesis/exports/boundary_eq_svd_diag.json'

def load_snapshot():
    c = np.loadtxt(P_C, dtype=float).reshape(N,2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    return c, r

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = 1.0 - y - r
    return s_xL, s_xR, s_yB, s_yT

def grad_row_boundary(i, kind, n=N):
    row = np.zeros(3*n, dtype=float)
    xi = 3*i; yi = xi + 1; ri = xi + 2
    if kind == 'xL':
        row[xi] = 1.0;  row[ri] = -1.0
    elif kind == 'xR':
        row[xi] = -1.0; row[ri] = -1.0
    elif kind == 'yB':
        row[yi] = 1.0;  row[ri] = -1.0
    elif kind == 'yT':
        row[yi] = -1.0; row[ri] = -1.0
    return row

def build_Aeq(c, r, tol=1e-8):
    s_xL, s_xR, s_yB, s_yT = slacks(c, r)
    rows = []
    for i in range(N):
        if s_xL[i] <= tol: rows.append(grad_row_boundary(i, 'xL'))
        if s_xR[i] <= tol: rows.append(grad_row_boundary(i, 'xR'))
        if s_yB[i] <= tol: rows.append(grad_row_boundary(i, 'yB'))
        if s_yT[i] <= tol: rows.append(grad_row_boundary(i, 'yT'))
    return np.vstack(rows) if rows else np.zeros((0, 3*N), dtype=float)

def construct_packing():
    c, r = load_snapshot()
    Aeq = build_Aeq(c, r, tol=1e-8)
    if Aeq.size > 0:
        U, S, Vh = np.linalg.svd(Aeq, full_matrices=True)
        svals = S.tolist()
        rank = int(np.sum(S > (1e-10 * (S.max() if S.size else 0.0))))
        null_dim = int(3*N - rank)
    else:
        svals = []; rank = 0; null_dim = 3*N
    out = {
        'Aeq_shape': [int(Aeq.shape[0]), int(Aeq.shape[1])],
        'singular_values': svals,
        'rank_est': rank,
        'nullspace_dim_est': null_dim
    }
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, 'w') as f:
        json.dump(out, f, indent=2)
    return c.astype(float), np.maximum(r - SAFETY, 1e-6).astype(float)
